        Assertions.assertEquals(32, pkg.ray.size(), "ray.0.0 segment count");
        assertClose("ray.0.0.op_delta", 239.18720540000007d, pkg.op_delta, 1.0e-6);
        var s0 = pkg.ray.get(0);
        assertClose("ray.0.0.0.p.x", 0.0d, s0.p.x, 1.0e-6);
        assertClose("ray.0.0.0.p.y", 0.0d, s0.p.y, 1.0e-6);
