        var opm = build();
        var third_order = ThirdOrder.compute_third_order(opm);
        double[] sum = new double[5];
        for (ThirdOrderData d : third_order.values()) {
            accumulate(sum, d.seidel());
            if (d.has_aspheric())
                accumulate(sum, d.aspheric());
        }
        var s1 = third_order.get(1).seidel();
        assertClose("seidel.1 S-I", 0.16719099644676844d, s1[0], 1.0e-12);
